mod solution;

fn main() {
    let cases = [
    (r#"[4,5,6,7,0,1,2]"#, r#"4"#),
    (r#"[0,1,2]"#, r#"0"#),
    (r#"
[0,1,2]
"#, r#"0"#),
    (r#"  
[4,5,6,7,0,1,2]
  "#, r#"4"#),
    ];
    for (case_index, (input, expected)) in cases.iter().enumerate() {
        if solution::solve(input) != *expected {
            eprintln!("PRIVATE CASE {} FAILED", case_index + 1);
            std::process::exit(1);
        }
    }
    println!("PASS rotated-search");
}
